//! The locked plugin corpus (18 §6), generated by `scripts/herdr-plugins-lock.ts`.
//!
//! The file is `tests/compat/herdr/0.9.3/plugins/top20.lock.toml`. Its shape:
//!
//! ```toml
//! schema = 1
//! baseline = "0.9.3"
//! catalog = "catalog.json"                 # relative to the lock file
//! catalog_sha256 = "…"
//! catalog_generated_at = "2026-10-11T10:00:42.514Z"
//! size = 20
//!
//! [toolchains]                             # pinned for every plugin job (18 §7.2)
//! node = "22.20.0"
//! bun = "1.3.0"
//! go = "1.25.1"
//! rust = "1.99.0"
//!
//! [[exclude]]
//! id = 1283376338
//! reason = "…"
//!
//! [[plugin]]
//! rank = 1
//! repository = "owner/repo"
//! repo_id = 1291255325
//! plugin_id = "owner.plugin"
//! manifest_path = "herdr-plugin/herdr-plugin.toml"
//! commit = "<40 hex>"
//! manifest_sha256 = "<64 hex>"
//! stars = 3800
//! created_at = "2026-07-06T16:31:11Z"
//! platforms = ["linux", "macos"]           # empty means all platforms
//! dependency_mode = "unpinned"             # or "verified"
//!
//! [[plugin.dependency]]                    # only in verified mode, filled by a record run
//! url = "https://…"
//! sha256 = "…"
//! ```

use serde::{Deserialize, Serialize};
use std::collections::BTreeMap;
use std::path::Path;

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct Lock {
    pub schema: u32,
    pub baseline: String,
    pub catalog: String,
    pub catalog_sha256: String,
    pub catalog_generated_at: String,
    pub size: usize,
    #[serde(default)]
    pub toolchains: BTreeMap<String, String>,
    #[serde(default)]
    pub exclude: Vec<Exclusion>,
    #[serde(default, rename = "plugin")]
    pub plugins: Vec<LockedPlugin>,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct Exclusion {
    pub id: u64,
    pub reason: String,
}

#[derive(Debug, Clone, Copy, Serialize, Deserialize, PartialEq, Eq, Hash)]
#[serde(rename_all = "snake_case")]
pub enum DependencyMode {
    Verified,
    Unpinned,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct LockedPlugin {
    pub rank: u32,
    pub repository: String,
    pub repo_id: u64,
    pub plugin_id: String,
    pub manifest_path: String,
    pub commit: String,
    pub manifest_sha256: String,
    pub stars: u64,
    pub created_at: String,
    #[serde(default)]
    pub platforms: Vec<String>,
    pub dependency_mode: DependencyMode,
    #[serde(default, rename = "dependency")]
    pub dependencies: Vec<LockedDependency>,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct LockedDependency {
    pub url: String,
    pub sha256: String,
}

